const translations: Record<WorkerLanguage, Record<WorkerTranslationKey, string>> = { uz, en, ko, ru };

export function normalizeWorkerLanguage(value: string | null | undefined): WorkerLanguage {
  return WORKER_LANGUAGES.some((item) => item.code === value) ? value as WorkerLanguage : "uz";
}

export function workerLocale(language: WorkerLanguage) {
  return language === "ko" ? "ko-KR" : language === "ru" ? "ru-RU" : language === "en" ? "en-US" : "uz-UZ";
}

export function translateWorker(
  language: WorkerLanguage,
  key: WorkerTranslationKey,
  variables: Record<string, string | number> = {},
) {
  return Object.entries(variables).reduce(
    (text, [name, value]) => text.replaceAll(`{{${name}}}`, String(value)),
    translations[language][key] || uz[key],
  );
}

const exactErrors: Record<string, WorkerTranslationKey> = {
  "PIN bilan kiring.": "error.loginRequired",
  "Login yoki PIN noto‘g‘ri.": "error.invalidLogin",
  "Ko‘p xato urinish bo‘ldi. 15 daqiqadan keyin qayta kiring.": "error.locked",
  "5 marta xato kiritildi. Akkaunt 15 daqiqaga bloklandi.": "error.lockedNow",
  "Rahbar davomat profilingizni xodim akkauntiga bog‘lamagan.": "error.profileUnlinked",
  "Bu vaqt uchun smena rahbar tomonidan oldin kiritilgan. Rahbar bilan tekshiring.": "error.shiftExists",
  "Ochiq smena topilmadi. Avval “KELDI”ni bosing.": "error.noOpenShift",
  "Ochiq smena topilmadi. Avval “ISHNI BOSHLADIM” tugmasini bosing.": "error.noOpenShift",
  "Ish vaqti hali boshlanmagan.": "error.notStarted",
  "Smena 18 soatdan oshgan. Rahbar vaqtni to‘g‘rilashi kerak.": "error.tooLong",
  "Bu vaqt ichida boshqa smena bor. Rahbar ish vaqtini to‘g‘rilashi kerak.": "error.shiftOverlap",
  "Sahifani yangilang.": "error.refresh",
  "Boshqa qurilmada ma’lumot yangilandi.": "error.refresh",
  "Ma’lumot yangilangan. Sahifani qayta oching.": "error.refresh",
  "Bu amal xodimga ruxsat etilmagan.": "error.notAllowed",
  "Avval HALO Telegram botini ulang.": "error.telegramSetup",
  "HALO bot username’i topilmadi.": "error.telegramSetup",
  "Ulash havolasi eskirgan. Yangi havola oling.": "error.telegramExpired",
  "Xodim havolani ochib START tugmasini bossin, keyin yana tekshiring.": "error.telegramStartFirst",
};

export function translateWorkerError(message: string, language: WorkerLanguage, fallback: WorkerTranslationKey) {
  const attemptMatch = message.match(/Login yoki PIN noto‘g‘ri\. (\d+) ta urinish qoldi\./);
  if (attemptMatch) return translateWorker(language, "error.invalidAttempts", { count: attemptMatch[1] });
  if (message.startsWith("Rahbar bugunni")) return translateWorker(language, "error.managerDayStatus");
  const key = exactErrors[message];
  if (key) return translateWorker(language, key);
  return language === "uz" && message ? message : translateWorker(language, fallback);
}
